<!doctype html><html><head><meta charset="utf-8"><style>body{font:11px Arial;color:#102a2a;margin:18px}h1{font-size:16px;margin:0}p{margin:4px 0;color:#54706d}table{width:100%;border-collapse:collapse;margin:14px 0}td{padding:4px 0}.amount{text-align:right}.total td{border-top:1px solid #d9e8e5;font-weight:bold;font-size:13px;padding-top:8px}</style></head><body><h1>{{ $shop->name }}</h1><p>Receipt #{{ str_pad($order->id, 5, '0', STR_PAD_LEFT) }} · {{ $order->created_at->format('M d, Y g:i A') }}</p><p>Cashier: {{ $order->cashier->name }}</p><table>@foreach($order->items as $item)<tr><td>{{ $item->variant->product->name }} × {{ $item->quantity }}</td><td class="amount">₱{{ number_format($item->subtotal,2) }}</td></tr>@endforeach<tr class="total"><td>Total</td><td class="amount">₱{{ number_format($order->total,2) }}</td></tr></table>@if($shop->receipt_footer)<p>{{ $shop->receipt_footer }}</p>@endif</body></html>
